        b = table_reader_get8( r );
        if ( i == 9 && b > 1 ) { r->offset = at; return 0; }
        *value |= (uint64_t) (b & 127) << (7*i);
        if ( (b & 128) == 0 ) { if ( i && b == 0 ) { r->offset = at; return 0; } return 1; }
