        if ( !table_reader_leb( &tail, &ref ) ) { break; }
        if ( ref == 0 ) { if ( tail.offset != tail.size ) { report->malformed = 1; return 0; } break; }
        if ( ref > count || !table_reader_has( &tail, 1 ) ) { break; }
