  if(kind==14){if(!table_message_leb(in,size,at,&v)||v>UINT32_MAX)return 0;
  f->min=(int64_t)v;
  }
  if(!table_message_leb(in,size,at,&v)||v>UINT32_MAX||v<(uint64_t)f->min)return 0;
